export function setupPlayer({onPlayback,toast}){
 const video=document.querySelector('#intro-video'),cinema=document.querySelector('#cinema'),controls=document.querySelector('#reel-controls'),overlay=document.querySelector('#reel-play'),toggle=document.querySelector('#reel-toggle'),seek=document.querySelector('#reel-seek'),mute=document.querySelector('#reel-mute'),volume=document.querySelector('#reel-volume'),full=document.querySelector('#reel-fullscreen');
 if(!video||!controls)return;
 const time=n=>`${Math.floor((n||0)/60).toString().padStart(2,'0')}:${Math.floor((n||0)%60).toString().padStart(2,'0')}`;
 function update(){const duration=Number.isFinite(video.duration)?video.duration:60;seek.max=String(duration);seek.value=String(video.currentTime);seek.setAttribute('aria-valuetext',`${Math.round(video.currentTime)} seconds of ${Math.round(duration)} seconds`);document.querySelector('#reel-time').textContent=`${time(video.currentTime)} / ${time(duration)}`;seek.style.setProperty('--seek-progress',`${video.currentTime/duration*100}%`);toggle.textContent=video.paused?'▶':'Ⅱ';toggle.setAttribute('aria-label',video.paused?'Play showreel':'Pause showreel');overlay.hidden=!video.paused;cinema.classList.toggle('is-playing',!video.paused);onPlayback(!video.paused);}
 async function playPause(){if(video.paused){try{await video.play();}catch{toast('Playback could not start. Please try again.');}}else video.pause();}
 overlay.onclick=playPause;toggle.onclick=playPause;video.addEventListener('click',playPause);video.tabIndex=0;
 video.addEventListener('keydown',e=>{if(e.code==='Space'||e.code==='Enter'){e.preventDefault();void playPause();}if(e.key==='ArrowRight'||e.key==='ArrowLeft'){e.preventDefault();video.currentTime=Math.max(0,Math.min(video.duration||60,video.currentTime+(e.key==='ArrowRight'?5:-5)));}});
 for(const type of ['play','pause','ended','loadedmetadata','timeupdate','seeking'])video.addEventListener(type,update);
 seek.addEventListener('input',()=>{const requested=Number(seek.value);if(video.readyState)video.currentTime=requested;else{video.addEventListener('loadedmetadata',()=>{video.currentTime=requested;},{once:true});video.load();}});
 function updateVolume(){const muted=video.muted||video.volume===0;mute.textContent=muted?'Sound off':'Sound on';mute.setAttribute('aria-label',muted?'Unmute video':'Mute video');mute.setAttribute('aria-pressed',String(muted));volume.value=String(video.volume);}
 mute.onclick=()=>{video.muted=!video.muted;updateVolume();};volume.oninput=()=>{video.volume=Number(volume.value);video.muted=false;updateVolume();};video.addEventListener('volumechange',updateVolume);
 function theater(enabled){cinema.classList.toggle('theater-mode',enabled);document.body.classList.toggle('no-scroll',enabled);document.querySelectorAll('header,footer,main>section:not(#film),#film>.section-top,#film>.film-caption').forEach(el=>el.inert=enabled);if(enabled){cinema.setAttribute('role','dialog');cinema.setAttribute('aria-modal','true');cinema.setAttribute('aria-label','Motion Showreel theater');}else{cinema.removeAttribute('role');cinema.removeAttribute('aria-modal');cinema.removeAttribute('aria-label');}full.setAttribute('aria-label',enabled?'Exit fullscreen':'Enter fullscreen');full.focus({preventScroll:true});}
 full.onclick=async()=>{if(cinema.classList.contains('theater-mode')){theater(false);return;}try{if(document.fullscreenElement)await document.exitFullscreen();else if(cinema.requestFullscreen)await cinema.requestFullscreen();else if(video.webkitEnterFullscreen)video.webkitEnterFullscreen();else theater(true);}catch{theater(true);}};
 document.addEventListener('fullscreenchange',()=>full.setAttribute('aria-label',document.fullscreenElement?'Exit fullscreen':'Enter fullscreen'));
 document.addEventListener('keydown',e=>{if(!cinema.classList.contains('theater-mode'))return;if(e.key==='Escape'){e.preventDefault();theater(false);}if(e.key==='Tab'){const items=[...cinema.querySelectorAll('button,input,video')].filter(el=>!el.hidden&&!el.disabled&&el.getClientRects().length);const first=items[0],last=items.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus();}}});
 video.addEventListener('error',()=>{video.controls=true;controls.hidden=true;overlay.hidden=true;toast('The video could not load. Please refresh to try again.');});
 controls.hidden=false;video.controls=false;update();updateVolume();
}
